package cn.zhuatech.searchai.service; import jakarta.validation.constraints.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class EnterpriseSearchService { public record Request(@NotBlank String query,@NotEmpty List<String> userDepartments,@NotEmpty List<String> requestedSources,boolean requireCitations){} public record Result(String normalizedQuery,List<String> permittedSources,List<String> blockedSources,List<String> retrievalPlan,boolean citationsRequired){} public Result plan(Request r){var permitted=r.requestedSources().stream().filter(s->r.userDepartments().stream().anyMatch(d->s.toLowerCase().contains(d.toLowerCase())||s.startsWith("public:"))).toList();var blocked=r.requestedSources().stream().filter(s->!permitted.contains(s)).toList();var steps=List.of("关键词与向量混合召回","按文档权限过滤","语义重排并去重","生成答案并保留段落级引用");return new Result(r.query().trim().replaceAll("\s+"," "),permitted,blocked,steps,r.requireCitations());} }
